import { describe, expect, it } from "vitest";
import { screen } from "@testing-library/react";
import {
  addRecord, chooseFilter, editRecord, expectNoRow, expectRow, reload,
  renderApp, row, rowTitles, runAction, stat,
} from "./test/helpers.js";

describe("journeys", () => {
  it("add a book and see it in the list", async () => {
    const { user } = renderApp();
    await addRecord(user, { Title: "Alpha", Author: "Ava", Category: "Novel" });
    expectRow("Alpha");
    expect(stat("Lent out")).toBe("0");
  });

  it("reject an empty required field", async () => {
    const { user } = renderApp();
    await addRecord(user, { Title: "", Author: "Ava", Category: "Novel" });
    expect(screen.getByText("Title: Title is required")).toBeVisible();
    expect(rowTitles()).toEqual([]);
  });

  it("edit an existing book", async () => {
    const { user } = renderApp();
    await addRecord(user, { Title: "Alpha", Author: "Ava", Category: "Novel" });
    await editRecord(user, "Alpha", { Title: "Alpha II" });
    expectRow("Alpha II");
    expectNoRow("Alpha");
  });

  it("delete a book added by mistake", async () => {
    const { user } = renderApp();
    await addRecord(user, { Title: "Alpha", Author: "Ava", Category: "Novel" });
    await removeRecord(user, "Alpha");
    expectNoRow("Alpha");
    expect(screen.getByText("Alpha deleted.")).toBeVisible();
  });

  it("lend a book and show the borrower", async () => {
    const { user } = renderApp();
    await addRecord(user, { Title: "Alpha", Author: "Ava", Category: "Novel" });
    await runAction(user, "Lend", "Alpha", "Sam");
    expectRow("Alpha", "Lent to Sam");
    expect(stat("Lent out")).toBe("1");
  });

  it("return a book and clear the borrower", async () => {
    const { user } = renderApp();
    await addRecord(user, { Title: "Alpha", Author: "Ava", Category: "Novel" });
    await runAction(user, "Lend", "Alpha", "Sam");
    await runAction(user, "Return", "Alpha");
    expectRow("Alpha", "Lent to Sam");
    expect(stat("Lent out")).toBe("0");
  });

  it("filter to see only books that are lent out", async () => {
    const { user } = renderApp();
    await addRecord(user, { Title: "Alpha", Author: "Ava", Category: "Novel" });
    await addRecord(user, { Title: "Beta", Author: "Bea", Category: "Novel" });
    await runAction(user, "Lend", "Alpha", "Sam");
    await chooseFilter(user, "Lent out");
    expectRow("Alpha", "Lent to Sam");
    expectNoRow("Beta");
  });

  it("filter to see only books that are at home", async () => {
    const { user } = renderApp();
    await addRecord(user, { Title: "Alpha", Author: "Ava", Category: "Novel" });
    await addRecord(user, { Title: "Beta", Author: "Bea", Category: "Novel" });
    await runAction(user, "Lend", "Alpha", "Sam");
    await chooseFilter(user, "At home");
    expectRow("Beta");
    expectNoRow("Alpha");
  });

  it("see how many books are lent out right now", async () => {
    const { user } = renderApp();
    await addRecord(user, { Title: "Alpha", Author: "Ava", Category: "Novel" });
    await addRecord(user, { Title: "Beta", Author: "Bea", Category: "Novel" });
    await runAction(user, "Lend", "Alpha", "Sam");
    await runAction(user, "Lend", "Beta", "Jo");
    expect(stat("Lent out")).toBe("2");
  });

  it("persist data across a browser refresh", async () => {
    const { user } = renderApp();
    await addRecord(user, { Title: "Alpha", Author: "Ava", Category: "Novel" });
    await addRecord(user, { Title: "Beta", Author: "Bea", Category: "Novel" });
    await runAction(user, "Lend", "Alpha", "Sam");
    expect(stat("Lent out")).toBe("1");
    reload();
    expectRow("Alpha", "Lent to Sam");
    expectRow("Beta");
    expect(stat("Lent out")).toBe("1");
  });
});

